-- ============================================================
-- 工业设备资产与报修管理系统 · 初始化数据
-- 内容：50 台设备 / 20 种备件 / 100 条工单 / 89 条维修记录 / 228 条巡检记录
-- 依赖：请先执行 07_建表脚本.sql
-- 说明：时间均以 NOW() 为基准向前推算，任何时间执行，看板趋势都覆盖最近 30 天
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 一、清空业务数据
DELETE FROM biz_repair_record;
DELETE FROM biz_inspect;
DELETE FROM biz_repair_order;
DELETE FROM biz_device;
DELETE FROM biz_part;
ALTER TABLE biz_repair_record AUTO_INCREMENT = 1;
ALTER TABLE biz_inspect AUTO_INCREMENT = 1;
ALTER TABLE biz_repair_order AUTO_INCREMENT = 1;
ALTER TABLE biz_device AUTO_INCREMENT = 1;
ALTER TABLE biz_part AUTO_INCREMENT = 1;

-- 二、备件库存（20 种）

-- 三、设备台账（50 台）

-- 四、报修工单（100 条：待受理 12 / 处理中 10 / 已完成 68 / 已取消 10）

-- 五、维修记录

-- 六、设备巡检（最近 30 天）

SET FOREIGN_KEY_CHECKS = 1;

-- 七、数据自检
SELECT 'biz_device' AS 表名, COUNT(*) AS 记录数 FROM biz_device
UNION ALL SELECT 'biz_part', COUNT(*) FROM biz_part
UNION ALL SELECT 'biz_repair_order', COUNT(*) FROM biz_repair_order
UNION ALL SELECT 'biz_repair_record', COUNT(*) FROM biz_repair_record
UNION ALL SELECT 'biz_inspect', COUNT(*) FROM biz_inspect;
